async function audio(){if(initPromise){await initPromise;await ctx.resume();return;}initPromise=(async()=>{ctx=new AudioContext({sampleRate:44100,latencyHint:'interactive'});await ctx.resume();const [bytes]=await Promise.all([fetch('engine.wasm').then(r=>{if(!r.ok)throw Error('Audio engine is missing.');return r.arrayBuffer();}),ctx.audioWorklet.addModule('processor.js')]);node=new AudioWorkletNode(ctx,'cut-a-dor',{numberOfInputs:0,numberOfOutputs:1,outputChannelCount:[2],processorOptions:{bytes}});node.port.onmessage=({data:m})=>{if(m.state){state=m.state;update();if(m.pattern)drawPattern(m.pattern);}if(m.error&&!m.request)say(m.error);if(m.request){const p=pending.get(m.request);if(p){clearTimeout(p.timer);pending.delete(m.request);m.error?p.reject(Error(m.error)):p.resolve(m.result);}}};node.onprocessorerror=()=>{$('#audio-state').textContent='AUDIO ERROR — RELOAD PAGE';say('The audio engine stopped. Please reload the page.');};node.connect(ctx.destination);$('#audio-state').textContent='AUDIO ON · SHARED C ENGINE';})();try{await initPromise;}catch(e){initPromise=null;throw e;}}
