async function getSound(s){if(s.data||s.pcm)return s;let data=soundCache.get(s.id);if(!data){const r=await fetch(`sounds/${s.id}.ima`);if(!r.ok)throw Error('Could not load sound.');data=new Uint8Array(await r.arrayBuffer());soundCache.set(s.id,data);}return {...s,data};}
