function drawLibrary(){const q=$('#search').value.toLocaleLowerCase();$('#library-list').replaceChildren();const sounds=library.filter(s=>(category<0||category===s.category)&&s.name.toLocaleLowerCase().includes(q));for(const s of sounds){const row=document.createElement('div');row.className='sound';const title=document.createElement('div');title.className='sound-title';const name=document.createElement('b');name.textContent=s.name;const meta=document.createElement('small');meta.textContent=`${cats[s.category].toUpperCase()} / ${(s.frames/s.rate).toFixed(2)} s${s.bpm?' / '+s.bpm+' BPM':''}`;title.append(name,meta);const play=document.createElement('button');play.className='preview';play.textContent='▶';play.setAttribute('aria-label',`${s.name} — preview`);play.onclick=safe(()=>preview(s));const assign=document.createElement('button');assign.textContent='PAD';assign.title='Assign to selected pad';assign.onclick=safe(async()=>{await send([21,selectedPad,s.index]);say(`${s.name} → Pad ${selectedPad+1}`);});const add=document.createElement('button');add.textContent='＋ BANK';add.onclick=safe(async()=>{if(bank.length>=16)throw Error('This bank already contains 16 sounds.');const sound=await getSound(s);if(bankBytes([...bank,sound])>81920)throw Error('This bank is full. Trim or remove a sound.');bank.push(sound);drawBank();say(`${s.name} added to bank.`);});row.append(play,title,assign,add);$('#library-list').append(row);}if(!sounds.length){const p=document.createElement('p');p.className='empty';p.textContent='No sounds found. Try another search or category.';$('#library-list').append(p);}}
$('#search').oninput=drawLibrary;['All',...cats].forEach((c,i)=>{const b=document.createElement('button');b.textContent=c;b.classList.toggle('active',i===0);b.onclick=()=>{category=i-1;all('#categories button').forEach(x=>x.classList.toggle('active',x===b));drawLibrary();};$('#categories').append(b);});
function drawSlots(){if(!library.length)return;$('#slot-map').replaceChildren();for(let i=0;i<16;i++){const b=document.createElement('button');b.classList.toggle('active',i===selectedPad);const n=document.createElement('small');n.textContent=`PAD ${String(i+1).padStart(2,'0')}`;const s=document.createElement('span');s.textContent=sampleById(state[40+i])?.name||'Empty';b.append(n,s);b.onclick=()=>{selectedPad=i;$('#slot-title').textContent=`PAD ${String(i+1).padStart(2,'0')} SELECTED`;drawSlots();};$('#slot-map').append(b);}}
function drawBank(){const total=bankBytes(bank);$('#bank-meter').value=total;$('#bank-budget').textContent=`${bank.length} Sounds · ${(total/1024).toFixed(1)} / 80 KiB${total>81920?' — PLEASE TRIM':''}`;$('#bank-list').replaceChildren();bank.forEach((s,i)=>{const row=document.createElement('div');row.className='bank-item';const area=document.createElement('div'),title=document.createElement('b');title.textContent=`${String(i+1).padStart(2,'0')} / ${s.name}`;const line=document.createElement('div');line.className='row';const cat=document.createElement('select');cats.forEach((c,j)=>cat.add(new Option(c,j)));cat.value=s.category;cat.setAttribute('aria-label',`Category for ${s.name}`);cat.onchange=()=>s.category=+cat.value;const dur=document.createElement('small');dur.textContent=`${(s.frames/s.rate).toFixed(2)} s`;const end=document.createElement('input');end.type='number';end.min=.02;end.max=s.frames/s.rate;end.step=.01;end.value=(s.frames/s.rate).toFixed(2);end.setAttribute('aria-label',`New length for ${s.name} in seconds`);const trim=document.createElement('button');trim.textContent='TRIM';trim.onclick=safe(async()=>{const target=Math.round(Number(end.value)*s.rate);if(!Number.isFinite(target)||target<160||target>s.frames)throw Error('Enter a valid shorter length.');const full=s.pcm||decodeIMA((await getSound(s)).data,s.frames),pcm=full.slice(0,target);for(let j=0;j<Math.min(64,pcm.length);j++)pcm[pcm.length-1-j]*=j/64;bank[i]={...s,pcm,frames:pcm.length,data:undefined};drawBank();});line.append(cat,dur,end,trim);area.append(title,line);const buttons=document.createElement('div');buttons.className='row';const listen=document.createElement('button');listen.textContent='▶';listen.setAttribute('aria-label',`${s.name} — preview bank sound`);listen.onclick=safe(()=>preview(s));const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label',`${s.name} — remove from bank`);remove.onclick=()=>{bank.splice(i,1);drawBank();};buttons.append(listen,remove);row.append(area,buttons);$('#bank-list').append(row);});}
async function importWavs(files){await audio();let added=0;for(const file of files){if(bank.length>=16){say('16-sound limit reached.');break;}if(file.size>32*1024*1024)throw Error('WAV too large: 32 MB maximum.');const ab=await file.arrayBuffer();if(new TextDecoder().decode(new Uint8Array(ab,0,Math.min(4,ab.byteLength)))!=='RIFF')throw Error('Please use a PCM WAV file.');const decoded=await ctx.decodeAudioData(ab);if(decoded.duration>24)throw Error(`${file.name}: trim to 24 seconds or less before importing.`);const offline=new OfflineAudioContext(1,Math.max(1,Math.round(decoded.duration*16000)),16000),source=offline.createBufferSource();source.buffer=decoded;source.connect(offline.destination);source.start();const rendered=await offline.startRendering(),pcm=rendered.getChannelData(0).slice();let peak=0;for(const x of pcm)peak=Math.max(peak,Math.abs(x));if(peak<1e-5)throw Error(`${file.name} contains no audible sound.`);const gain=.8/Math.max(.8,peak);for(let i=0;i<pcm.length;i++)pcm[i]*=gain;for(let i=0;i<Math.min(32,pcm.length);i++){pcm[i]*=i/32;pcm[pcm.length-1-i]*=i/32;}bank.push({name:file.name.replace(/\.wav$/i,'').slice(0,15),category:7,pcm,frames:pcm.length,rate:16000});added++;drawBank();}drawBank();say(`${added} WAV${added===1?'':'s'} imported. Choose a category and trim if needed.`);}
