for(let i=0;i<34;i++){const n=document.createElement('span');n.className='pattern-number';n.textContent=i<2?'':i===2?'1':i===18?'2':(i-2)%4===0?String(((i-2)%16)/4+1):'·';patternGrid.append(n);}
for(let t=0;t<8;t++){
 const label=document.createElement('span');label.className='pattern-label';label.textContent=cats[t].split(' /')[0].toUpperCase();patternGrid.append(label);
 const roll=document.createElement('button');roll.className='track-roll';roll.textContent='↻';roll.setAttribute('aria-label',`Reroll ${cats[t]} track`);roll.title=`Replace only ${cats[t]}; Undo to restore`;roll.onclick=safe(()=>send([25,t,0]));patternGrid.append(roll);
 for(let st=0;st<32;st++){const b=document.createElement('button');b.className=`step-cell track-${t}${st%4===0?' beat':''}${st===16?' half':''}`;b.setAttribute('aria-label',`${cats[t]}, bar ${Math.floor(st/16)+1}, step ${st%16+1}`);b.setAttribute('aria-pressed','false');b.onclick=safe(async()=>{selectedStep=t*32+st;await send([24,t,st]);});b.onfocus=()=>{selectedStep=t*32+st;drawStepControls();};patternGrid.append(b);cells.push(b);}
}
function drawPattern(pattern){lastPattern=pattern;drawStepControls();for(let i=0;i<256;i++){const b=cells[i],value=pattern[i];b.setAttribute('aria-pressed',String(value>0));b.classList.toggle('ghost',value>0&&value<65);b.classList.toggle('cursor',!!state[0]&&i%32===state[2]);}$('#pattern-status').textContent=`PART ${state[3]?'B':'A'} / ${pattern.slice(0,256).filter(x=>x>0).length} HITS / 32 STEPS`;}
function drawStepControls(){
 const t=Math.floor(selectedStep/32),st=selectedStep%32;
 $('#selected-step').textContent=`${cats[t].toUpperCase()} · BAR ${Math.floor(st/16)+1} · STEP ${st%16+1}`;
 const v=lastPattern[selectedStep]||0,raw=lastPattern[256+selectedStep]||0,n=raw>127?raw-256:raw;
 if(document.activeElement!==$('#step-velocity'))$('#step-velocity').value=v;
 if(document.activeElement!==$('#step-nudge'))$('#step-nudge').value=n;
 $('#step-velocity-value').value=v;$('#step-nudge-value').value=n;
 cells.forEach((c,i)=>c.classList.toggle('selected',i===selectedStep));
}
$('#step-velocity').oninput=safe(e=>send([29,Math.floor(selectedStep/32),(selectedStep%32)+(+e.target.value<<5)]));
$('#step-nudge').oninput=safe(e=>send([30,Math.floor(selectedStep/32),(selectedStep%32)+((+e.target.value+8)<<5)]));
$('#step-ghost').onclick=safe(()=>send([29,Math.floor(selectedStep/32),(selectedStep%32)+(35<<5)]));
$('#step-accent').onclick=safe(()=>send([29,Math.floor(selectedStep/32),(selectedStep%32)+(118<<5)]));
$('#step-off').onclick=safe(()=>send([29,Math.floor(selectedStep/32),selectedStep%32]));
$('#step-undo').onclick=safe(()=>send([7,0,0]));
$('#mutate').onclick=safe(()=>send([23,0,0]));
$('#crate-flip').onclick=safe(async()=>{const current=state[24],next=(current+1+Math.floor(Math.random()*11))%12;await send([2,8,next]);say(`Crate flip: ${kits[next]}. Your rhythm stays in place.`);});
$('#bounce').onclick=safe(async()=>{
 const button=$('#bounce');button.disabled=true;button.textContent='BOUNCING…';let worker;
 try{const project=await query('export'),wasm=await fetch('engine.wasm').then(r=>r.arrayBuffer()),banks=bankLoaded.map(s=>s.length?packBank(s):null),bars=+$('#bounce-bars').value;
  worker=new Worker('bounce-worker.mjs',{type:'module'});const bytes=await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Bounce timed out. Try again.')),30000);worker.onmessage=({data:m})=>{clearTimeout(timeout);m.error?reject(Error(m.error)):resolve(m.bytes);};worker.onerror=()=>{clearTimeout(timeout);reject(Error('Bounce worker failed.'));};worker.postMessage({project,wasm,banks,bars});});
  download(bytes,`cut-a-dor-${state[16]}bpm-${bars}bars.wav`,'audio/wav');say('WAV ready: 44.1 kHz / 16-bit mono, with your saved FX tape.');
 }finally{worker?.terminate();button.disabled=false;button.textContent='↓ WAV FOR YOUR SAMPLER';}
});

// Curated banks load in the browser only. Device writing remains an explicit step.
const crates=['dusty-room','velvet-cut','break-pit'],crateNames=['DUSTY ROOM','VELVET CUT','BREAK PIT'];
for(const button of document.querySelectorAll('[data-crate]'))button.onclick=safe(async()=>{
 const slot=+button.dataset.crate;const response=await fetch(`soundbanks/${crates[slot]}.cadb`);
 if(!response.ok)throw Error('Could not load the expansion bank.');
 const bytes=new Uint8Array(await response.arrayBuffer()),sounds=unpackBank(bytes);
 await query('bank',{slot,bytes});bank=sounds;bankLoaded[slot]=sounds;selectedBank=slot;
 $('#bank-slot').value=String(slot);$('#bank-name').value=crateNames[slot];$('#bank-replace-ok').checked=false;
 await send([2,8,12+slot]);breakOptions();drawBank();drawSlots();refreshPads();
 say(`${crateNames[slot]} loaded into browser Bank ${slot+1}. Select Beat Dojo and press Start. Device unchanged.`);
});
function route(){if(['#crate','#guide','#dojo'].includes(location.hash))document.querySelector(`[data-tab="${location.hash.slice(1)}"]`).click();}
window.addEventListener('hashchange',route);route();
